// HOSA Bowl Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items. HOSA facts follow the Valus HOSA lessons (HOSA Handbook and
// The First Fifty Years); current health topics use well-established public health issues.
import {q, mix} from './q.js';
const DHO='Simmers, DHO: Health Science', BSF='Scott & Bell, Body Structures and Functions', TAB='Taber’s Cyclopedic Medical Dictionary', MLP='NIH MedlinePlus', BRIEF='Robert’s Rules of Order Newly Revised In Brief', HB='HOSA Handbook and website';
const HOSA='HOSA Related Knowledge', PP='Parliamentary Procedure', AP='Anatomy and Physiology', MT='Medical Terminology', CUR='Current Health Topics', OTH='Remaining Categories';
const HM='History of Medicine', HS='Healthcare Systems', HC='Health Careers', LE='Legal and Ethical Practices', NUT='Nutrition', SAF='Safety', INF='Infection Control', MATH='Math Conversions';

export default {
 id:'hosa-bowl-2',
 event:'HOSA Bowl',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'DHO: Health Science, Body Structures and Functions, Taber’s, NIH MedlinePlus, RONR In Brief and HOSA publications',
 plan:[{area:HOSA,weight:12},{area:PP,weight:12},{area:AP,weight:12},{area:MT,weight:12},{area:CUR,weight:12},{area:OTH,weight:40,topics:[HM,HS,HC,LE,NUT,SAF,INF,MATH]}],
 questions:mix([
  q(HOSA,'Which HOSA divisions are support divisions rather than active student divisions?','Alumni and professional',['Middle school and secondary','Secondary and postsecondary','Collegiate and professional'],'A','Middle school, secondary and postsecondary/collegiate members are active students; alumni and professional members support them.',HB),
  q(HOSA,'Which HOSA publication celebrates the organization’s fiftieth anniversary?','The First Fifty Years 1976–2026',['The HOSA Handbook, Section D','The Voting Delegate Packet','The Health Science Almanac'],'B','The First Fifty Years 1976–2026 tells the story of HOSA’s founding, early leaders, conferences and growth over five decades.',HB),
  q(HOSA,'How long does an Executive Council officer serve after being elected at ILC?','One year',['Two years','Four years','Until graduation'],'C','Executive Council officers are elected at ILC with the participation of voting delegates and serve a one-year term.',HB),
  q(HOSA,'Through which level do students normally become HOSA members?','A local chapter',['The Executive Council','HOSA Headquarters','A sponsor organization'],'D','Students join through a local chapter, which affiliates with its chartered association and the international organization.',HB),
  q(HOSA,'Who leads a chartered association and plays a key role in selecting its voting delegates?','The State Advisor',['The chapter president','The Executive Council','The event sponsor'],'A','State Advisors coordinate chartered associations; delegate selection is at their discretion or follows the association’s bylaws.',HB),
  q(HOSA,'What determines how many voting delegates a chartered association sends to ILC?','Its membership size',['Its number of event winners','Its distance from ILC','Its number of advisors'],'B','Delegates are allocated from a membership table—for example, 101–1,000 members earn 2 delegates and 1,001–3,000 earn 3.',HB),
  q(PP,'Which motion kills a main motion without a direct vote on it?','Postpone indefinitely',['Postpone to a certain time','Lay on the table','Commit or refer'],'C','Postpone indefinitely disposes of the main motion for the session; it is debatable and needs only a majority vote.',BRIEF),
  q(PP,'Under Robert’s Rules, how many times may a member speak on the same question on the same day?','Twice',['Once','Three times','As often as desired'],'D','Each member may speak twice per question per day, and may not speak a second time while anyone who has not spoken wishes to.',BRIEF),
  q(PP,'What vote does the motion to suspend the rules usually require?','A two-thirds vote',['A majority vote','A tie vote','A plurality vote'],'A','Suspending the rules sets aside members’ normal protections, so it usually needs two-thirds; bylaws themselves cannot be suspended.',BRIEF),
  q(PP,'Which motion sends a pending question to a small group for study and recommendation?','Commit or refer',['Lay on the table','Previous question','Postpone indefinitely'],'B','The motion to commit or refer sends a question to a committee, often with instructions on when and how to report back.',BRIEF),
  q(PP,'A member believes a rule is being violated. What should the member say?','“Point of order”',['“I move to adjourn”','“Call the question”','“I move to rescind”'],'C','A point of order asks the chair to enforce the rules. It may interrupt a speaker and does not require a second.',BRIEF),
  q(PP,'Which motion is privileged and, when adopted, ends the meeting?','Adjourn',['Rescind','Recess','Reconsider'],'D','Adjourn ends the meeting. Recess only provides a short break, after which business resumes where it stopped.',BRIEF),
  q(AP,'Which heart valve lies between the left atrium and the left ventricle?','Mitral valve',['Tricuspid valve','Pulmonary valve','Aortic valve'],'A','The mitral valve has two cusps and prevents backflow into the left atrium; the tricuspid valve lies on the right side.',BSF),
  q(AP,'Where is the heart’s natural pacemaker, the SA node, located?','In the wall of the right atrium',['In the wall of the left ventricle','In the interventricular septum','At the base of the aorta'],'B','The sinoatrial node in the right atrium starts each impulse, which then passes to the AV node, bundle of His and Purkinje fibers.',BSF),
  q(AP,'In which structures does gas exchange occur in the lungs?','Alveoli',['Bronchi','Trachea','Pleura'],'C','Oxygen and carbon dioxide diffuse across the thin walls of the alveoli and the surrounding pulmonary capillaries.',BSF),
  q(AP,'Which cells in the pancreatic islets secrete insulin?','Beta cells',['Alpha cells','Acinar cells','Delta cells'],'D','Beta cells of the islets of Langerhans secrete insulin to lower blood glucose; alpha cells secrete glucagon to raise it.',BSF),
  q(AP,'Which is the longest and strongest bone in the human body?','Femur',['Tibia','Humerus','Fibula'],'A','The femur, or thigh bone, runs from the hip to the knee and supports body weight during standing and walking.',BSF),
  q(AP,'Which blood components are essential for forming a clot?','Platelets',['Erythrocytes','Neutrophils','Lymphocytes'],'B','Platelets clump at an injury and release clotting factors, which leads to the fibrin mesh that forms a stable clot.',BSF),
  q(MT,'What does the term hepatomegaly mean?','Enlargement of the liver',['Inflammation of the liver','Pain in the liver','Removal of the liver'],'C','Hepat/o (liver) + -megaly (enlargement). Inflammation is -itis, pain is -algia and removal is -ectomy.',TAB),
  q(MT,'Which suffix means “surgical repair”?','-plasty',['-stomy','-tomy','-pexy'],'D','-plasty means surgical repair, -stomy means a new opening, -tomy means incision and -pexy means surgical fixation.',TAB),
  q(MT,'Which prefix means “half”?','hemi-',['hyper-','hypo-','homo-'],'A','Hemi- means half, as in hemiplegia (paralysis of one side). Hyper- means above, hypo- below and homo- same.',TAB),
  q(MT,'What does the abbreviation PRN mean on a medication order?','As needed',['By mouth','Before meals','Every night'],'B','PRN comes from the Latin pro re nata. PO means by mouth, ac means before meals and qhs means at bedtime.',TAB),
  q(MT,'What does the term dyspnea mean?','Difficult breathing',['Absence of breathing','Rapid breathing','Normal breathing'],'C','Dys- (difficult) + -pnea (breathing). Apnea is absence, tachypnea is rapid and eupnea is normal breathing.',TAB),
  q(MT,'What does the abbreviation BID mean?','Twice a day',['Every other day','At bedtime','Four times a day'],'D','BID (bis in die) means twice a day. QID means four times a day and TID means three times a day.',TAB),
  q(CUR,'Why did H5N1 avian influenza draw public health attention in 2024 and 2025?','It spread to dairy cattle and infected some farm workers',['It became the leading cause of death in teenagers','It was eliminated worldwide by vaccination','It began spreading easily between all mammals'],'A','H5N1 spread among U.S. dairy herds and caused human infections in farm workers, raising concern about possible adaptation to humans.',MLP),
  q(CUR,'Why did the FDA approve naloxone nasal spray for over-the-counter sale in 2023?','To widen access to opioid overdose reversal',['To treat chronic pain without a prescription','To replace vaccines for opioid users','To prevent fentanyl from being manufactured'],'B','Naloxone rapidly reverses opioid overdose. Over-the-counter sale lets families, schools and bystanders keep it on hand.',MLP),
  q(CUR,'What is the 988 Suicide & Crisis Lifeline?','A three-digit number for mental health crises',['A hotline only for poison exposures','A federal program for opioid prescriptions','A tool for reporting hospital fraud'],'C','Launched in 2022, 988 connects callers and texters to trained crisis counselors, as 911 does for emergency services.',MLP),
  q(CUR,'Why have GLP-1 receptor agonists such as semaglutide been widely discussed?','They treat type 2 diabetes and obesity',['They cure antibiotic-resistant infections','They replace insulin in type 1 diabetes','They prevent all forms of heart disease'],'D','These drugs lower blood glucose and reduce appetite, and high demand for weight loss has caused shortages and cost debates.',MLP),
  q(CUR,'What is “long COVID”?','Symptoms that persist months after infection',['A COVID infection lasting over a year','A new strain that spreads more slowly','A vaccine side effect in older adults'],'A','Long COVID describes symptoms such as fatigue, brain fog and shortness of breath that continue for at least three months after infection.',MLP),
  q(CUR,'What is one major concern about using artificial intelligence in health care?','Bias in the data used to train it',['It cannot process any medical images','It never makes errors in diagnosis','It must be used only in rural clinics'],'B','AI tools can reflect biases in their training data and raise privacy concerns, so they need validation and human oversight.',MLP),
  q(HM,'Who discovered X-rays in 1895?','Wilhelm Röntgen',['Marie Curie','Louis Pasteur','Robert Koch'],'C','Röntgen discovered X-rays while experimenting with cathode-ray tubes, transforming diagnosis by letting physicians see inside the body.',DHO),
  q(HM,'Who introduced antiseptic surgery using carbolic acid?','Joseph Lister',['Edward Jenner','William Harvey','Florence Nightingale'],'D','Building on Pasteur’s germ theory, Lister used carbolic acid on wounds and instruments, sharply reducing surgical infections.',DHO),
  q(HM,'Who is considered the founder of modern nursing?','Florence Nightingale',['Clara Barton','Dorothea Dix','Elizabeth Blackwell'],'A','Nightingale improved sanitation in Crimean War hospitals and founded a nursing school, establishing nursing as a profession.',DHO),
  q(HS,'Which program is jointly funded by federal and state governments to cover people with low incomes?','Medicaid',['Medicare','TRICARE','Workers’ compensation'],'B','Medicaid is a federal–state program for low-income people; Medicare is federal insurance mainly for people 65 and older.',DHO),
  q(HS,'How does a preferred provider organization (PPO) differ from a typical HMO?','Members may see out-of-network providers at higher cost',['Members must always choose a primary care gatekeeper','Members can never see a specialist','Members pay nothing for any service'],'C','PPOs allow more choice, including out-of-network care at higher cost, while HMOs usually require in-network care and referrals.',DHO),
  q(HS,'Which federal agency approves prescription drugs as safe and effective?','The Food and Drug Administration',['The Centers for Disease Control','The Department of Labor','The Environmental Protection Agency'],'D','The FDA regulates drugs, medical devices and food safety; the CDC focuses on disease prevention and public health.',DHO),
  q(HC,'Which professional designs, fits and adjusts artificial limbs?','Prosthetist',['Orthoptist','Podiatrist','Audiologist'],'A','Prosthetists make artificial limbs. Orthoptists treat eye movement disorders, podiatrists treat feet and audiologists treat hearing.',DHO),
  q(HC,'Which degree is now required for new physical therapists in the United States?','Doctor of Physical Therapy',['Associate of Applied Science','Bachelor of Science in Health','Master of Health Administration'],'B','Physical therapists now earn a Doctor of Physical Therapy (DPT) and must pass a national licensing exam to practice.',DHO),
  q(HC,'A central supply technician who sterilizes and distributes equipment works in which pathway?','Support services',['Diagnostic services','Therapeutic services','Health informatics'],'C','Support services careers create a safe, efficient environment for care, including central supply, environmental services and maintenance.',DHO),
  q(HC,'What does the term “scope of practice” describe?','Tasks a professional is legally allowed to do',['The number of patients seen in each shift','The geographic area that a clinic serves','The salary range for a health career'],'D','Scope of practice is defined by state law and licensing boards; working outside it can lead to legal action and loss of license.',DHO),
  q(LE,'What is an advance directive?','A document stating a person’s wishes for future care',['A doctor’s order for immediate treatment','A bill sent before a procedure','A hospital’s staffing policy'],'A','Advance directives such as a living will or health care power of attorney guide care if the patient cannot speak for themself.',DHO),
  q(LE,'A worker spreads false spoken statements that damage a patient’s reputation. What is this?','Slander',['Libel','Assault','Battery'],'B','Defamation is false statements that harm reputation; slander is spoken and libel is written. Assault is a threat and battery is touching.',DHO),
  q(LE,'Which element must be proven, along with duty, breach and causation, for negligence?','Damages or injury to the patient',['Intent to harm the patient','A written contract with the patient','Criminal charges against the worker'],'C','Negligence requires a duty, a breach of that duty, harm caused by the breach and resulting damages; intent is not required.',DHO),
  q(NUT,'Which vitamin deficiency causes scurvy, with bleeding gums and poor wound healing?','Vitamin C',['Vitamin A','Vitamin D','Vitamin K'],'D','Vitamin C is needed to form collagen. Without it, gums bleed and wounds heal poorly; citrus fruits are good sources.',DHO),
  q(NUT,'Which mineral is a key part of hemoglobin and is needed to carry oxygen?','Iron',['Calcium','Sodium','Iodine'],'A','Iron forms the center of the heme group in hemoglobin; deficiency causes iron-deficiency anemia with fatigue and pallor.',DHO),
  q(SAF,'What does the RACE acronym stand for in a health care fire?','Rescue, Alarm, Contain, Extinguish',['Run, Alert, Call, Exit','Remove, Assess, Cover, Evacuate','Report, Act, Clear, Escape'],'B','RACE sets the order of actions in a fire: rescue people in danger, sound the alarm, contain the fire and then extinguish or evacuate.',DHO),
  q(SAF,'Which document gives information about a chemical’s hazards, handling and first aid?','Safety data sheet (SDS)',['Incident report','Material requisition','Patient care plan'],'C','OSHA requires a safety data sheet for each hazardous chemical, listing hazards, protective equipment, first aid and spill steps.',DHO),
  q(INF,'Which statement about the chain of infection is correct?','Breaking any one link can stop the spread',['All six links must be broken at once','Only the causative agent can be targeted','The chain applies only to bacteria'],'A','The chain runs from agent to reservoir, portal of exit, mode of transmission, portal of entry and susceptible host; breaking any link stops it.',DHO),
  q(MATH,'A patient’s temperature is 39 °C. What is it in degrees Fahrenheit?','102.2 °F',['100.4 °F','103.6 °F','98.6 °F'],'B','°F = (°C × 1.8) + 32, so 39 × 1.8 = 70.2, and 70.2 + 32 = 102.2 °F.',DHO),
  q(MATH,'How many milligrams are in 1.5 grams?','1,500 mg',['15 mg','150 mg','15,000 mg'],'D','There are 1,000 mg in 1 gram, so 1.5 g × 1,000 = 1,500 mg. Move the decimal three places to the right.',DHO)
 ],4129)
};
